CREATE TABLE members(user_id VARCHAR(36) PRIMARY KEY,nickname VARCHAR(40) NOT NULL,host_name VARCHAR(80) NOT NULL,last_seen BIGINT NOT NULL,revoked BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE discussions(id VARCHAR(36) PRIMARY KEY,author_id VARCHAR(36) NOT NULL,title VARCHAR(100) NOT NULL,body LONGTEXT NOT NULL,created_at VARCHAR(40) NOT NULL);
CREATE TABLE comments(id VARCHAR(36) PRIMARY KEY,discussion_id VARCHAR(36) NOT NULL,author_id VARCHAR(36) NOT NULL,body LONGTEXT NOT NULL,created_at VARCHAR(40) NOT NULL,FOREIGN KEY(discussion_id) REFERENCES discussions(id));
CREATE TABLE event_log(seq BIGINT AUTO_INCREMENT PRIMARY KEY,event_id VARCHAR(36) NOT NULL UNIQUE,kind VARCHAR(80) NOT NULL,payload LONGTEXT NOT NULL,created_at VARCHAR(40) NOT NULL);
CREATE TABLE replica_nodes(id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36) NOT NULL,name VARCHAR(80) NOT NULL,credential_hash VARCHAR(64) NOT NULL UNIQUE,revoked BOOLEAN NOT NULL DEFAULT FALSE,last_seen BIGINT NOT NULL);
